"% Inputs
W = 230000.0;       % lbf
S = 2400.0;         % ft^2
h = 31000.0;        % ft
V = 730.0;          % ft/s
CL0 = 0.15;
CLalpha = 5.2;      % per rad
CD0 = 0.021;
k = 0.043;
rho0 = 0.0023769;   % slug/ft^3
H_scale = 23800;    % ft
T0 = 62000.0;       % lbf at V0 = 730 ft/s
V0 = 730.0;         % ft/s

% Atmosphere (simple exponential)
rho = rho0 * exp(-h/H_scale);
qbar = 0.5 * rho * V^2;

% Steady level-flight trim: lift equals weight
CL_trim = W / (qbar * S);

% Angle of attack from lift curve (CL = CL0 + CLalpha*alpha)
alpha_trim_rad = (CL_trim - CL0) / CLalpha;
alpha_trim_deg = alpha_trim_rad * 180 / pi;

% Drag from drag polar; required thrust equals drag in steady level flight
CD_trim = CD0 + k * CL_trim^2;
thrust_lbf = qbar * S * CD_trim;

% Write result.json
result = struct('alpha_trim_deg', alpha_trim_deg, 'thrust_lbf', thrust_lbf);
fid = fopen('result.json', 'w');
fwrite(fid, jsonencode(result), 'char');
fclose(fid);"
